def validate_field_semantics(doc):
    META = {'id','n','severity','item','loss','meta','phase','agent','date','subject','as_of',
            'A_manual_settings_edit','B_unregister_mcp','C_plugin_uninstall',
            'CRITICAL','MAJOR','ADVISORY','ba','pm','coordinator_challenges','findings',
            'b_redefine_nfr1','c_per_server_opt_in','adr018_minimum_viable_set','lazy_connect',
            'NFR-1','NFR-2','NFR-3','NFR-4','NFR-5','FR-23'}
    META |= {'FIND-%02d' % i for i in range(1, 11)}
    bad = []
    def walk(o, path):
        if isinstance(o, list):
            for i, x in enumerate(o): walk(x, '%s[%d]' % (path, i))
        elif isinstance(o, dict):
            for k, v in o.items():
                if not (k in META or k.endswith('_now') or k.endswith('_record')
                        or k.endswith('_as_filed') or k.startswith('_')):
                    bad.append('%s.%s' % (path, k))
                walk(v, '%s.%s' % (path, k))
    # SCOPE: every top-level section except the contract itself.
    for cont in [k for k in doc if not k.startswith('_')]:
        walk(doc[cont], cont)
    return bad
